-- Look & feel defaults. Colors, radius, gaps and blur strength are overridden by the
-- active theme (~/.config/devy/current/hypr.lua, generated by `devy-theme`).
--
-- Motion: short and calm. Hyprland animation speed is in deciseconds (2 = 200 ms).
-- Blur: 2 passes is the sweet spot on an iGPU; new_optimizations + xray keep it cheap.

hl.config({
  general = {
    gaps_in = 5,
    gaps_out = 10,
    border_size = 2,
    resize_on_border = true,
    allow_tearing = false,
    layout = "dwindle",
  },

  decoration = {
    rounding = 12,
    rounding_power = 2,
    active_opacity = 1.0,
    inactive_opacity = 1.0,

    shadow = {
      enabled = true,
      range = 12,
      render_power = 3,
      color = 0x55000000,
    },

    blur = {
      enabled = true,
      size = 6,
      passes = 2,
      new_optimizations = true,
      xray = false,
      noise = 0.01,
      vibrancy = 0.17,
      popups = true,
    },
  },

  animations = {
    enabled = true,
  },

  dwindle = {
    preserve_split = true,
  },
})

hl.curve("devyOut",  { type = "bezier", points = { {0.23, 1},   {0.32, 1} } })
hl.curve("devyIn",   { type = "bezier", points = { {0.4, 0},    {1, 1}    } })
hl.curve("linear",   { type = "bezier", points = { {0, 0},      {1, 1}    } })
hl.curve("devySpring", { type = "spring", mass = 1, stiffness = 238.1191, damping = 24.21279333 })

hl.animation({ leaf = "global",        enabled = true, speed = 10,  bezier = "default" })
hl.animation({ leaf = "border",        enabled = true, speed = 4,   bezier = "devyOut" })
hl.animation({ leaf = "windows",       enabled = true, speed = 3.5, spring = "devySpring" })
hl.animation({ leaf = "windowsIn",     enabled = true, speed = 2.5, bezier = "devyOut", style = "popin 92%" })
hl.animation({ leaf = "windowsOut",    enabled = true, speed = 1.5, bezier = "devyIn",  style = "popin 92%" })
hl.animation({ leaf = "fade",          enabled = true, speed = 2,   bezier = "devyOut" })
hl.animation({ leaf = "layersIn",      enabled = true, speed = 2,   bezier = "devyOut", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true, speed = 1.5, bezier = "linear",  style = "fade" })
hl.animation({ leaf = "workspaces",    enabled = true, speed = 2.5, bezier = "devyOut", style = "slide" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = 2.5, bezier = "devyOut", style = "slidevert" })
